async function assertKpiOwnerScope(req, ownerUserId) {
  const ownerId = Number(ownerUserId);
  if (!Number.isInteger(ownerId) || ownerId < 1) {
    throw Object.assign(new Error("Select an active Finance employee."), {
      status: 400,
      code: "FINANCE_KPI_OWNER_REQUIRED",
    });
  }
  if (ownerId === Number(req.user.id) ||
      req.financeAccess.accessLevel === "security_admin" ||
      (req.financeAccess.reportingScope || []).includes(ownerId)) {
    return ownerId;
  }
  throw Object.assign(new Error("You may manage KPIs only for yourself or employees in your governed Finance reporting scope."), {
    status: 403,
    code: "FINANCE_KPI_OWNER_SCOPE_DENIED",
  });
}

router.get("/access-context", financeAccess.accessContext);
router.get("/my-work", async (req,res,next) => {
  try {
    const userId=Number(req.user.id);
    const tickets=await pool.query(`SELECT t.id,t.ticket_ref reference,t.title,t.status,t.priority,t.created_at,t.updated_at,t.due_at,t.effective_due_at,t.original_due_at,fo.evidence_state,fo.kpi_objective,fo.kpi_period,t.confidentiality_level,t.assigned_to_user_id,COALESCE(fo.finance_function,t.category,'General Finance Administration') finance_function,'ticket' work_type,
      EXTRACT(EPOCH FROM (NOW()-t.created_at))/NULLIF(EXTRACT(EPOCH FROM (COALESCE(t.effective_due_at,t.due_at)-t.created_at)),0) elapsed_ratio,
      (SELECT r.review_status FROM finance_task_reviews r WHERE r.ticket_id=t.id ORDER BY r.id DESC LIMIT 1) review_status,
      (SELECT r.rating FROM finance_task_reviews r WHERE r.ticket_id=t.id ORDER BY r.id DESC LIMIT 1) rating
      FROM tickets t LEFT JOIN finance_ticket_operations fo ON fo.ticket_id=t.id
      WHERE t.workspace='FIN' AND t.assigned_to_user_id=$1 AND t.status NOT IN ('Resolved','Closed')
      ORDER BY t.due_at NULLS LAST,t.priority='Critical' DESC,t.created_at DESC LIMIT 250`,[userId]);
    let closeTasks=[];
    try{closeTasks=(await pool.query(`SELECT t.id,t.task_reference reference,t.title,t.status,'Medium' priority,t.created_at,t.updated_at,t.due_at,t.effective_due_at,t.original_due_at,t.evidence_state,t.kpi_objective,t.kpi_period,t.confidentiality_level,t.owner_user_id assigned_to_user_id,t.finance_function,'month_end' work_type,t.review_status,NULL::numeric rating,
      EXTRACT(EPOCH FROM (NOW()-t.created_at))/NULLIF(EXTRACT(EPOCH FROM (COALESCE(t.effective_due_at,t.due_at)-t.created_at)),0) elapsed_ratio,t.requires_evidence,
      (SELECT COUNT(*)::int FROM finance_close_task_evidence e WHERE e.task_id=t.id) evidence_count
      FROM finance_close_tasks t WHERE t.owner_user_id=$1 AND t.status NOT IN ('completed','closed','skipped') ORDER BY t.due_at NULLS LAST`,[userId])).rows}catch(error){if(error.code!=='42P01')throw error;warnSchemaDrift({route:"/api/finance-workspace/my-work",table:"finance_close_tasks",error});}
    let journals=[];try{journals=(await pool.query(`SELECT j.id,j.journal_reference reference,j.description title,j.status,'Medium' priority,j.created_at,j.updated_at,j.due_at,j.effective_due_at,j.original_due_at,j.evidence_state,j.kpi_objective,j.kpi_period,j.confidentiality_level,j.preparer_user_id assigned_to_user_id,'journal' work_type,NULL::numeric elapsed_ratio,NULL review_status,NULL::numeric rating FROM finance_journals j WHERE j.preparer_user_id=$1 AND j.status NOT IN ('posted','reversed') ORDER BY j.due_at NULLS LAST`,[userId])).rows}catch(error){if(!['42P01','42703'].includes(error.code))throw error;warnSchemaDrift({route:"/api/finance-workspace/my-work",table:"finance_journals",error});}
    let reconciliations=[];try{reconciliations=(await pool.query(`SELECT r.id,r.reconciliation_reference reference,r.control_name title,r.status,'Medium' priority,r.created_at,r.updated_at,r.due_at,r.effective_due_at,r.original_due_at,r.evidence_state,r.kpi_objective,r.kpi_period,r.confidentiality_level,r.owner_user_id assigned_to_user_id,'reconciliation' work_type,NULL::numeric elapsed_ratio,NULL review_status,NULL::numeric rating FROM finance_reconciliations r WHERE r.owner_user_id=$1 AND r.status NOT IN ('posted','reversed') ORDER BY r.due_at NULLS LAST`,[userId])).rows}catch(error){if(!['42P01','42703'].includes(error.code))throw error;warnSchemaDrift({route:"/api/finance-workspace/my-work",table:"finance_reconciliations",error});}
    const allItems=[...tickets.rows,...closeTasks,...journals,...reconciliations];
    const normalized=allItems.map(x=>{const effectiveDue=x.effective_due_at||x.due_at;const isOverdue=Boolean(effectiveDue&&new Date(effectiveDue)<new Date());const dueWithin24h=Boolean(effectiveDue&&new Date(effectiveDue)-Date.now()<=86400000&&new Date(effectiveDue)>new Date());const dueToday=Boolean(effectiveDue&&new Date(effectiveDue).toDateString()===new Date().toDateString());const dueThisWeek=Boolean(effectiveDue&&!isOverdue&&new Date(effectiveDue)<=new Date(Date.now()+7*86400000));const evidenceRequired=Boolean(x.evidence_state==='required'||(x.requires_evidence&&!(x.evidence_count>0)));return{...x,elapsedPercent:x.elapsed_ratio==null?null:Math.max(0,Math.round(Number(x.elapsed_ratio)*100)),isOverdue,dueWithin24h,dueToday,dueThisWeek,evidenceRequired};});
    const summary={open:normalized.length,overdue:normalized.filter(x=>x.isOverdue).length,due24h:normalized.filter(x=>x.dueWithin24h&&!x.isOverdue).length,dueToday:normalized.filter(x=>x.dueToday).length,dueThisWeek:normalized.filter(x=>x.dueThisWeek).length,halfElapsed:normalized.filter(x=>Number(x.elapsedPercent)>=50&&!x.isOverdue).length,returned:normalized.filter(x=>String(x.status).toLowerCase().includes('returned')||String(x.review_status).toLowerCase()==='returned').length,awaitingReview:normalized.filter(x=>String(x.status).toLowerCase()==='awaiting_review'||String(x.review_status).toLowerCase()==='awaiting_review'||String(x.review_status).toLowerCase()==='pending').length,evidenceRequired:normalized.filter(x=>x.evidenceRequired).length};
    let emailAttention=[];try{emailAttention=(await pool.query(`SELECT c.id,c.subject,c.received_at,c.management,c.important,c.acknowledged_at,m.display_name mailbox_name FROM finance_correspondence c JOIN finance_mailboxes m ON m.id=c.mailbox_id WHERE c.assigned_to_user_id=$1 AND c.acknowledged_at IS NULL AND c.status<>'closed' ORDER BY c.management DESC,c.important DESC,c.received_at DESC LIMIT 50`,[userId])).rows}catch(e){if(['42P01','42703'].includes(e?.code)){warnSchemaDrift({route:"/api/finance-workspace/my-work",table:"finance_correspondence",error:e});}else{console.warn(JSON.stringify({warningCode:"WORK_ENRICHMENT_FAILED",route:"/api/finance-workspace/my-work",errorCode:e?.code||"UNKNOWN",message:e?.message||String(e),timestamp:new Date().toISOString()}));}}
    res.json({summary,items:normalized,emailAttention,generatedAt:new Date().toISOString()});
  } catch(error){next(error);}
});

