router.get("/employees", managers, async (_req,res,next) => { try { const result=await pool.query(`SELECT u.id,u.name,u.email,u.job_title,u.department,u.manager_name,COALESCE(fr.office_code,'MAIN_CFO') office_code,COALESCE(fr.finance_function,'General Finance Administration') finance_function,COALESCE(fr.availability_status,'available') availability_status,COALESCE(fr.delegation_eligible,TRUE) delegation_eligible,COALESCE(fr.is_finance_manager,FALSE) is_finance_manager,(SELECT COUNT(*)::int FROM tickets t WHERE t.assigned_to_user_id=u.id AND t.status NOT IN ('Resolved','Closed')) open_workload FROM users u LEFT JOIN finance_employee_responsibilities fr ON fr.user_id=u.id WHERE u.archived_at IS NULL AND u.status='active' AND u.account_type='person' AND (LOWER(COALESCE(u.department,'')) LIKE '%finance%' OR fr.active=TRUE) ORDER BY u.name`); res.json({employees:result.rows,functions:financeFunctions}); } catch(error){next(error);} });
router.put("/employees/:userId", managers, async (req,res,next) => { try { const body=req.body||{}; if(String(req.params.userId)!==String(req.user.id))financeDelegatedAuthorityService.assertWithinAuthority(req.financeAccess,req.params.userId);financeDelegatedAuthorityService.assertNotSelfRolePromotion(req.user.id,req.params.userId,body.isFinanceManager?"manager":(body.role||null)); if(!financeFunctions.includes(body.financeFunction)) return res.status(400).json({error:"Invalid Finance function."}); const result=await pool.query(`INSERT INTO finance_employee_responsibilities(user_id,office_code,finance_function,manager_user_id,backup_user_id,availability_status,delegation_eligible,is_finance_manager,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(user_id) DO UPDATE SET office_code=EXCLUDED.office_code,finance_function=EXCLUDED.finance_function,manager_user_id=EXCLUDED.manager_user_id,backup_user_id=EXCLUDED.backup_user_id,availability_status=EXCLUDED.availability_status,delegation_eligible=EXCLUDED.delegation_eligible,is_finance_manager=EXCLUDED.is_finance_manager,updated_at=NOW() RETURNING *`,[req.params.userId,body.officeCode||"MAIN_CFO",body.financeFunction,body.managerUserId||null,body.backupUserId||null,body.availabilityStatus||"available",body.delegationEligible!==false,Boolean(body.isFinanceManager),req.user.id]); res.json(result.rows[0]); } catch(error){next(error);} });
