router.get("/correspondence",async(req,res,next)=>{try{await financeCorrespondence.ensureSchema();const filter=String(req.query.filter||"attention");const clauses=["c.status<>'closed'"];if(filter==="attention")clauses.push("(c.important=TRUE OR c.management=TRUE OR c.acknowledged_at IS NULL OR c.response_due_at<NOW() OR c.obligation_due_at<NOW())");if(filter==="management")clauses.push("c.management=TRUE");if(filter==="external")clauses.push("c.external=TRUE");if(filter==="overdue")clauses.push("(c.response_due_at<NOW() OR c.obligation_due_at<NOW())");const items=await pool.query(`SELECT c.*,u.name assignee_name,m.display_name mailbox_name,(COALESCE(c.obligation_due_at,c.response_due_at)<NOW() AND c.status<>'closed') is_overdue FROM finance_correspondence c JOIN finance_mailboxes m ON m.id=c.mailbox_id LEFT JOIN users u ON u.id=c.assigned_to_user_id WHERE ${clauses.join(" AND ")} ORDER BY c.management DESC,c.important DESC,COALESCE(c.obligation_due_at,c.response_due_at) NULLS LAST,c.received_at DESC LIMIT 500`);const s=(await pool.query(`SELECT COUNT(*) FILTER(WHERE important=TRUE AND status<>'closed')::int important,COUNT(*) FILTER(WHERE management=TRUE AND acknowledged_at IS NULL AND status<>'closed')::int management_waiting,COUNT(*) FILTER(WHERE acknowledged_at IS NULL AND status<>'closed')::int unacknowledged,COUNT(*) FILTER(WHERE response_due_at<NOW() AND acknowledged_at IS NULL AND status<>'closed')::int response_overdue,COUNT(*) FILTER(WHERE obligation_due_at<NOW() AND status<>'closed')::int obligation_overdue,COUNT(*) FILTER(WHERE last_activity_at<NOW()-INTERVAL '24 hours' AND status<>'closed')::int stale_24h FROM finance_correspondence`)).rows[0];const failures=(await pool.query("SELECT COUNT(*)::int count FROM finance_mailboxes WHERE active=TRUE AND monitoring_enabled=TRUE AND last_sync_status='failed'")).rows[0].count;res.json({summary:{important:s.important,managementWaiting:s.management_waiting,unacknowledged:s.unacknowledged,responseOverdue:s.response_overdue,obligationOverdue:s.obligation_overdue,stale24h:s.stale_24h,syncFailures:failures},items:items.rows,sync:{configured:Boolean(process.env.MICROSOFT_TENANT_ID&&process.env.MICROSOFT_CLIENT_ID&&process.env.MICROSOFT_CLIENT_SECRET)}})}catch(error){next(error)}});
