router.get("/activity-feed",async(req,res,next)=>{
  try{
    const page=Math.max(1,Number(req.query.page)||1);
    const limit=Math.min(200,Number(req.query.limit)||100);
    const offset=(page-1)*limit;
    const filters=[];
    const params=[];
    if(req.query.actionType){params.push(req.query.actionType);filters.push("a.action_type=$"+params.length)}
    if(req.query.employeeId){params.push(Number(req.query.employeeId));filters.push("a.actor_user_id=$"+params.length)}
    if(req.query.from){params.push(req.query.from);filters.push("a.created_at>=$"+params.length)}
    if(req.query.to){params.push(req.query.to);filters.push("a.created_at<=$"+params.length)}
    const where=filters.length?"WHERE "+filters.join(" AND "):"";
    const r=await pool.query("SELECT a.actor_user_id,a.action_type,a.work_item_id,a.work_item_reference,a.work_item_title,a.action_detail,a.created_at action_timestamp,u.name actorName FROM finance_governance_actions a LEFT JOIN users u ON u.id=a.actor_user_id "+where+" ORDER BY a.created_at DESC LIMIT "+limit+" OFFSET "+offset,params);
    const count=await pool.query("SELECT COUNT(*)::int total FROM finance_governance_actions a "+where,params);
    res.json({entries:r.rows,total:count.rows[0].total,page,limit});
  }catch(e){next(e)}
});
router.get("/kpi-risk/:employeeId/contributing-items",async(req,res,next)=>{
  try{
    const employeeId=Number(req.params.employeeId);
    const period=req.query.period||new Date().toISOString().slice(0,7);
    const items=await pool.query("SELECT s.work_item_id,s.work_item_type,s.objective_name,s.item_score,s.timeliness_score,s.quality_score,COALESCE(t.ticket_ref,j.journal_reference,rc.reconciliation_reference,ct.task_reference) reference,COALESCE(t.title,j.description,rc.control_name,ct.title) title,"+financeManagerDashboard.TARGET_KPI_SCORE+"-s.item_score gapToTarget FROM finance_kpi_item_scores s LEFT JOIN tickets t ON t.id=s.work_item_id AND s.work_item_type='ticket' LEFT JOIN finance_journals j ON j.id=s.work_item_id AND s.work_item_type='journal' LEFT JOIN finance_reconciliations rc ON rc.id=s.work_item_id AND s.work_item_type='reconciliation' LEFT JOIN finance_close_tasks ct ON ct.id=s.work_item_id AND s.work_item_type='month_end' WHERE s.period_key=ANY($1::text[]) AND s.reviewer_user_id=$2 ORDER BY gapToTarget DESC",[financePeriodService.containedMonthlyKeys(period),employeeId]);
    const projection=items.rows.length?items.rows.reduce((sum,x)=>sum+Number(x.item_score),0)/items.rows.length:0;
    res.json({employeeId,period,items:items.rows.map(x=>({...x,item_score:Number(x.item_score),timeliness_score:Number(x.timeliness_score),quality_score:Number(x.quality_score),gapToTarget:Number(x.gaptotarget)})),projectedScore:Math.round(projection*100)/100,targetScore:financeManagerDashboard.TARGET_KPI_SCORE,shortfall:Math.max(0,financeManagerDashboard.TARGET_KPI_SCORE-projection)});
  }catch(e){next(e)}
});
router.get("/people-performance/duties",async(req,res,next)=>{try{const r=await pool.query("SELECT d.*,u.name employee_name,f.name function_name FROM finance_employee_duties d JOIN users u ON u.id=d.user_id LEFT JOIN finance_functions f ON f.id=d.finance_function_id WHERE ($1::bigint IS NULL OR d.user_id=$1) ORDER BY u.name,d.weight DESC",[req.query.userId||null]);res.json({duties:r.rows})}catch(e){next(e)}});
router.post("/people-performance/duties",async(req,res,next)=>{try{const b=req.body||{};const r=await pool.query(`INSERT INTO finance_employee_duties(user_id,finance_function_id,duty_name,duty_description,weight,progress_percent,status,target_date,created_by,updated_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,$9) RETURNING *`,[b.userId,b.financeFunctionId||null,b.dutyName,b.dutyDescription||null,Number(b.weight||0),Math.max(0,Math.min(100,Number(b.progressPercent||0))),b.status||'not_started',b.targetDate||null,req.user.id]);res.status(201).json(r.rows[0])}catch(e){next(e)}});
