router.post("/governance/access/:id/decision",async(req,res,next)=>{const c=await pool.connect();try{const b=req.body||{};if(!['approve','reject','override_approve','revoke'].includes(b.decision))return res.status(400).json({error:'Invalid access decision'});if(['reject','override_approve','revoke'].includes(b.decision)&&String(b.reason||'').trim().length<5)return res.status(400).json({error:'A reason is required'});await c.query('BEGIN');const x=(await c.query("SELECT * FROM finance_access_requests WHERE id=$1 FOR UPDATE",[req.params.id])).rows[0];if(!x)return res.status(404).json({error:'Access request not found'});const status=b.decision==='approve'?'approved':b.decision==='reject'?'rejected':b.decision==='override_approve'?'approved_override':'revoked';await c.query("UPDATE finance_access_requests SET status=$2,manager_decision_at=CASE WHEN $3 IN('approve','reject') THEN NOW() ELSE manager_decision_at END,manager_reason=CASE WHEN $3 IN('approve','reject') THEN $4 ELSE manager_reason END,admin_override=CASE WHEN $3='override_approve' THEN TRUE ELSE admin_override END,override_by=CASE WHEN $3='override_approve' THEN $5 ELSE override_by END,override_reason=CASE WHEN $3='override_approve' THEN $4 ELSE override_reason END,grant_source=CASE WHEN $3='override_approve' THEN 'administrative_override' WHEN $3='approve' THEN 'manager_approval' ELSE grant_source END,granted_at=CASE WHEN $3 IN('approve','override_approve') THEN NOW() ELSE granted_at END,revoked_at=CASE WHEN $3='revoke' THEN NOW() ELSE revoked_at END,revoked_by=CASE WHEN $3='revoke' THEN $5 ELSE revoked_by END,updated_at=NOW() WHERE id=$1",[x.id,status,b.decision,b.reason||null,req.user.id]);await c.query("INSERT INTO finance_governance_actions(record_type,record_id,action,actor_user_id,reason,detail) VALUES('access_request',$1,$2,$3,$4,$5::jsonb)",[x.id,b.decision,req.user.id,b.reason||null,JSON.stringify({grantSource:b.decision==='override_approve'?'administrative_override':'manager_approval'})]);await c.query('COMMIT');res.json({ok:true,status})}catch(e){await c.query('ROLLBACK').catch(()=>{});next(e)}finally{c.release()}});
