router.get("/month-end/:period",async(req,res,next)=>{try{let p=(await pool.query("SELECT * FROM finance_close_periods WHERE period_key=$1",[req.params.period])).rows[0];if(!p)return res.json({period:null,tasks:[],summary:{weightedProgress:0,outstanding:0,overdue:0,awaitingReview:0}});const r=await pool.query(`SELECT t.*,o.name owner_name,b.name backup_name,rv.name reviewer_name,(SELECT COUNT(*)::int FROM finance_close_task_evidence e WHERE e.task_id=t.id) evidence_count FROM finance_close_tasks t LEFT JOIN users o ON o.id=t.owner_user_id LEFT JOIN users b ON b.id=t.backup_user_id LEFT JOIN users rv ON rv.id=t.reviewer_user_id WHERE t.period_id=$1 ORDER BY t.due_at NULLS LAST,t.task_reference`,[p.id]);const s=await pool.query(`SELECT ROUND(COALESCE(SUM(weight*progress_percent)/NULLIF(SUM(weight),0),0),2) weighted_progress,COUNT(*) FILTER(WHERE status NOT IN('completed','closed'))::int outstanding,COUNT(*) FILTER(WHERE due_at<NOW() AND status NOT IN('completed','closed'))::int overdue,COUNT(*) FILTER(WHERE review_status='pending' AND status='awaiting_review')::int awaiting_review FROM finance_close_tasks WHERE period_id=$1`,[p.id]);res.json({period:p,tasks:r.rows,summary:{weightedProgress:Number(s.rows[0].weighted_progress||0),outstanding:s.rows[0].outstanding,overdue:s.rows[0].overdue,awaitingReview:s.rows[0].awaiting_review}})}catch(e){next(e)}});
