router.put("/tasking/participants/:ticketId/:participantId/access",async(req,res,next)=>{try{const b=req.body||{};const r=await pool.query(`UPDATE finance_task_participants SET can_view=$3,can_comment=$4,can_edit=$5 WHERE ticket_id=$1 AND id=$2 RETURNING *`,[req.params.ticketId,req.params.participantId,b.canView!==false,b.canComment!==false,Boolean(b.canEdit)]);res.json(r.rows[0]||null)}catch(e){next(e)}});

router.get("/my-kpi",async(req,res,next)=>{try{const userId=Number(req.user.id);const period=req.query.period||new Date().toISOString().slice(0,7);const aggregation=await financeKpiScoring.aggregateObjectiveScores({employeeUserId:userId,periodKey:period});let trend=null;if(/^\d{4}-\d{2}$/.test(period)){const prevPeriod=new Date(period+"-01");prevPeriod.setMonth(prevPeriod.getMonth()-1);const prevKey=prevPeriod.toISOString().slice(0,7);const prevAggregation=await financeKpiScoring.aggregateObjectiveScores({employeeUserId:userId,periodKey:prevKey});trend=prevAggregation.overallScore!=null&&aggregation.overallScore!=null?Math.round((aggregation.overallScore-prevAggregation.overallScore)*100)/100:null;}res.json({period,objectives:aggregation.objectives,overallScore:aggregation.overallScore,weightWarning:aggregation.weightWarning,trend,generatedAt:new Date().toISOString()});}catch(e){next(e)}});

router.get("/kpi-scores",async(req,res,next)=>{try{const userId=req.query.userId?Number(req.query.userId):Number(req.user.id);const period=req.query.period||new Date().toISOString().slice(0,7);if(userId!==Number(req.user.id)&&!["manager","workspace_manager","security_admin"].includes(req.financeAccess?.accessLevel))return res.status(403).json({error:"Manager scope required to view other employee KPI scores."});const scores=(await pool.query(`SELECT s.*,o.name objective_label FROM finance_kpi_item_scores s LEFT JOIN finance_kpi_objectives o ON o.name=s.objective_name WHERE s.period_key=ANY($1::text[]) AND s.work_item_id IN (SELECT id FROM tickets WHERE assigned_to_user_id=$2::bigint UNION SELECT id FROM finance_close_tasks WHERE owner_user_id=$2::bigint) ORDER BY s.calculated_at DESC`,[financePeriodService.containedMonthlyKeys(period),userId])).rows;const aggregation=await financeKpiScoring.aggregateObjectiveScores({employeeUserId:userId,periodKey:period});res.json({period,userId,scores,objectives:aggregation.objectives,overallScore:aggregation.overallScore});}catch(e){next(e)}});

router.post("/kpi-scores/recalculate",async(req,res,next)=>{try{const period=req.body.period||null;const result=await financeKpiScoring.recalculateAllScores(period);res.json({ok:true,...result});}catch(e){next(e)}});

router.get("/kpi-objectives",async(_req,res,next)=>{try{const r=await pool.query("SELECT * FROM finance_kpi_objectives ORDER BY weight DESC");res.json({objectives:r.rows});}catch(e){next(e)}});

router.post("/extensions",async(req,res,next)=>{try{const b=req.body||{};const result=await financeExtensionService.createExtensionRequest({workItemId:b.workItemId,workItemType:b.workItemType,requestedDueAt:b.requestedDueAt,reason:b.reason,dependencyType:b.dependencyType,requestedBy:req.user.id});res.status(201).json(result);}catch(e){next(e)}});

router.post("/extensions/:id/decision",async(req,res,next)=>{try{const b=req.body||{};const result=await financeExtensionService.decideOnExtension({extensionId:Number(req.params.id),decision:b.decision,approverUserId:req.user.id,rejectionReason:b.rejectionReason,dependencyType:b.dependencyType});res.json(result);}catch(e){next(e)}});

router.post("/approvals/:type/:id/exempt",async(req,res,next)=>{try{const type=req.params.type==='journals'?'journal':req.params.type==='reconciliations'?'reconciliation':req.params.type;if(!['journal','reconciliation','ticket','month_end'].includes(type))return res.status(400).json({error:'Invalid approval type'});const b=req.body||{};const result=await financeReviewExemption.grantExemption({workItemId:Number(req.params.id),workItemType:type,reason:b.reason,approverUserId:req.user.id});res.status(201).json(result);}catch(e){next(e)}});

router.get("/portfolios/:portfolio/items", async (req, res, next) => {
  try {
    const portfolio = req.params.portfolio;
    const status = req.query.status || null;
    const priority = req.query.priority || null;
    const assignee = req.query.assignee ? Number(req.query.assignee) : null;
    const period = req.query.period || null;
    const scope = financeAccess.ticketScope(req, 5);
    const tickets = await pool.query(
      `SELECT t.id,t.ticket_ref reference,t.title,t.status,t.priority,t.due_at,t.effective_due_at,
              fo.kpi_objective,fo.kpi_period,t.assigned_to_user_id,u.name assignee_name,'ticket' work_type
       FROM tickets t
       LEFT JOIN finance_ticket_operations fo ON fo.ticket_id=t.id
       LEFT JOIN users u ON u.id=t.assigned_to_user_id
       WHERE t.workspace='FIN'
         AND COALESCE(fo.finance_function,'General Finance Administration')=$1
         AND ($2::text IS NULL OR t.status=$2)
         AND ($3::text IS NULL OR t.priority=$3)
         AND ($4::bigint IS NULL OR t.assigned_to_user_id=$4)
         AND ${scope.sql}
       ORDER BY t.due_at NULLS LAST,t.created_at DESC
       LIMIT 500`,
      [portfolio, status, priority, assignee, ...scope.params]
    );
    res.json({ portfolio, items: tickets.rows, filters: { status, priority, assignee, period } });
  } catch (error) {
    next(error);
  }
});

router.get("/reminders/status",managers,async(_req,res,next)=>{try{const lastRun=(await pool.query("SELECT MAX(last_sent_at) last_run FROM finance_task_reminders WHERE enabled=TRUE")).rows[0]?.last_run;const byType=(await pool.query("SELECT reminder_type,COUNT(*)::int count,COUNT(*) FILTER(WHERE last_sent_at IS NOT NULL)::int sent FROM finance_task_reminders WHERE enabled=TRUE GROUP BY reminder_type ORDER BY reminder_type")).rows;const failed=(await pool.query("SELECT COUNT(*)::int count FROM finance_task_reminders WHERE enabled=TRUE AND last_sent_at IS NULL AND created_at<NOW()-INTERVAL '1 hour'")).rows[0].count;res.json({lastRun,nextRun:"every 10 minutes",sent:byType.reduce((s,t)=>s+t.sent,0),failed,queued:byType.reduce((s,t)=>s+t.count-t.sent,0),byType});}catch(e){next(e)}});

